<?php
$queueSql="SELECT a.*,c.full_name customer_name,s.name service_name,th.full_name therapist_name FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN therapists th ON th.id=a.therapist_id WHERE a.appointment_date=CURDATE() AND a.source='walk_in' AND a.status IN ('checked_in','in_session','pending','confirmed')";$params=[];if(is_therapist()){$queueSql.=' AND a.therapist_id=?';$params[]=(int)(current_user()['therapist_id']??0);}$queueSql.=' ORDER BY a.created_at';$q=db()->prepare($queueSql);$q->execute($params);$queue=$q->fetchAll();
$customers=db()->query("SELECT id,full_name,customer_code FROM customers WHERE status='active' ORDER BY full_name")->fetchAll();$services=db()->query("SELECT id,name,duration_minutes,price FROM services WHERE status='active' ORDER BY name")->fetchAll();$therapists=db()->query("SELECT id,full_name FROM therapists WHERE status='active' AND availability_status='available' ORDER BY full_name")->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">Front desk</div><h1>Walk-in queue</h1><p>Register a guest, select a service, and assign an available therapist.</p></div><div class="d-flex gap-2"><a href="<?=h(app_page_url('customers',['new'=>1,'return'=>'walkins']))?>" class="btn btn-outline-secondary">Register customer</a></div></div>
<?php if(is_staff()):?><div class="card mb-4"><div class="card-header">Add walk-in customer</div><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="walkin"><div class="col-lg-4"><label class="form-label">Customer *</label><select name="customer_id" class="form-select" required><option value="">Select existing customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['full_name'])?> · <?=h($c['customer_code'])?></option><?php endforeach;?></select></div><div class="col-lg-3"><label class="form-label">Service *</label><select name="service_id" class="form-select" required><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=h($s['name'])?> · <?=money($s['price'])?></option><?php endforeach;?></select></div><div class="col-lg-3"><label class="form-label">Therapist *</label><select name="therapist_id" class="form-select" required><option value="">Select therapist</option><?php foreach($therapists as $t):?><option value="<?=$t['id']?>"><?=h($t['full_name'])?></option><?php endforeach;?></select></div><div class="col-lg-2 d-flex align-items-end"><button class="btn btn-primary w-100"><i class="bi bi-person-check me-1"></i>Check in</button></div></form><div class="form-text mt-2">A customer must have an active profile. Use “Register customer” first for new guests. An active therapist booking conflict is checked before the walk-in is added.</div></div></div><?php endif;?>
<div class="card"><div class="card-header d-flex justify-content-between"><span>Live queue · <?=date('F j, Y')?></span><span class="badge text-bg-light"><?=count($queue)?> waiting / active</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Queue</th><th>Customer</th><th>Service</th><th>Therapist</th><th>Start</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$queue)echo table_empty(7,'No active walk-ins right now.');foreach($queue as $i=>$a):?><tr><td><span class="queue-number"><?=str_pad((string)($i+1),3,'0',STR_PAD_LEFT)?></span></td><td class="fw-semibold"><?=h($a['customer_name'])?><div class="small-muted"><?=h($a['appointment_code'])?></div></td><td><?=h($a['service_name'])?></td><td><?=h($a['therapist_name'])?></td><td><?=date('g:i A',strtotime($a['start_time']))?></td><td><?=status_badge($a['status'])?></td><td class="text-end"><?php if(is_staff()):?><a class="btn btn-sm btn-primary" href="<?=h(app_page_url('pos',['appointment_id'=>$a['id']]))?>">Checkout</a><?php else:?><?=post_form_start('appointment_status',app_page_url('walkins'))?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="in_session"><button class="btn btn-sm btn-light">Start session</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
